package com.example.starter.race.api;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Positive;

/**
 * 新建赛事请求。
 *
 * @param raceId      赛事ID，全局唯一
 * @param baseStartMs 赛事基准（枪声）起跑时刻，Unix 毫秒时间戳（UTC）；
 *                    可空表示创建时不设基准，此类赛事不能登记波次
 * @param requestId   全局唯一请求ID（幂等键）
 */
public record CreateRaceRequest(
        @NotBlank String raceId,
        @Positive Long baseStartMs,
        @NotBlank String requestId
) {
}

package com.example.starter.race.api;

import com.example.starter.race.domain.RaceStatus;

/**
 * 赛事信息响应。
 *
 * @param raceId      赛事ID
 * @param version     当前版本号（从1开始）
 * @param status      OPEN / SEALED
 * @param baseStartMs 赛事基准（枪声）起跑时刻（Unix 毫秒时间戳，UTC）；创建时未设置为 null
 * @param createdAt   创建时间，Unix毫秒时间戳
 */
public record RaceResponse(
        String raceId,
        int version,
        RaceStatus status,
        Long baseStartMs,
        long createdAt
) {
}

